1. 클래스(Class)


    겍체지향 프로그래밍(OOP; Object-Oriented Programming)에서 특정 객체를 생성하기 위해 변수와 메소드를 정의하는 일종의 틀.

      변수(Variable)와 메소드(Method)로 구성

    C++ 클래스 예제
      #include &lt;iostream&gt;
using namespace std;

class A {         //클래스명을 A로 지정
  public:         //외부에서 접근할 수 있도록 설정
    void fn(){    //메소드명 fn 지정
      cout &lt;&lt; "메소드" &lt;&lt; endl;    //"메소드"라는 글자 출력
    }
}

void main(){
  A *a = new A();   // a라는 이름의 클래스 A 변수 설정
  a-&gt;fn();          // a라는 변수의 fn 메소드 실행
}


    Java 클래스 예제
      public class A {        //클래스명을 A로 지정
  public void fn(){     // 메소드명 fn, 외부접근 가능하도록 설정(public)
    System.out.println("메소드");      //"메소드"라는 글자 출력
  }

  public static void main(String[] args){
    A a = new A();               // a라는 이름의 클래스 A 변수 설정
    a.fn();                   // a라는 변수의 fn 메소드 실행
  }
}


    파이썬 클래스 예제
