    C++ 클래스내 사용자 정의함수 예제
      #include &lt;iostream&gt;
using namespace std;

class A {         //클래스명을 A로 지정
  public:         //외부에서 접근할 수 있도록 설정
    int sum;
    int add(int a, int b){    //메소드명 add 지정 / 정수 a, b 입력 받음
      sum = a+b;            // sum 에 a+b 저장  
      return sum;           //sum 반환
    }
};

void main(){
