2. 상속(Inheritance)



      상속이란 어떤 객체가 있을 때 그 객체의 변수와 메소드를 다른 객체가 물려받을 수 있는 기능.

    C++ 상속 예제
      #include &lt;iostream&gt;
using namespace std;

class A{            //클래스 A 지정
  public:           //외부접근 설정
    void fnA(){     //메소드명 fnA 
      cout &lt;&lt; "A 클래스" &lt;&lt; endl;    // "A 클래스" 글자 출력
    }
};

class B: public A{      //A클래스를 상속받은 클래스 B 지정
  public:               //외부접근 설정
    void fnB(){         //메소드명 fnB
      cout &lt;&lt; "B 클래스" &lt;&lt; endl;    // "B 클래스" 글자 출력
    }
}

void main(){
  B *b = new B();     //b라는 이름의 클래스 B에 대한 변수 설정
  b-&gt;fnA();           //b라는 변수로 fnA 메소드 실행
  b-&gt;fnB();           //b라는 변수로 fnB 메소드 실행
}


    Java 상속 예제
      public class A{             //클래스 A 지정
  public void fnA(){        //메소드명 fnA, 외부접근 설정 
    System.out.println("A 클래스");        // "A 클래스" 글자 출력
  }
}

public class B extends A {           //클래스 B 지정
  public void fnB(){                 //메소드명 fnB, 외부접근 설정 
    System.out.println("B 클래스");   // "B 클래스" 글자 출력
  }
}

public class MainTest{
  public static void main(String[] args){
    B b = new B();      //b라는 이름의 클래스 B에 대한 변수 설정
    b.fnA();           //b라는 변수로 fnA 메소드 실행
    b.fnB();           //b라는 변수로 fnB 메소드 실행
  }
}


    파이썬 상속 예제
      class A:            # 클래스명 A 지정
  def fnA():        # 메소드명 fnA
    print('A 클래스')    # 'A 클래스' 글자 출력

class B(A):            # 클래스명 B는 A를 상속받음
  def fnB():           # 메소드명 fnB
    print('B 클래스')    # 'B 클래스' 글자 출력

b = B       # b라는 이름의 클래스 B에 대한 변수 설정
b.fnA();    # b 라는 변수로 fnA 메소드 실행
b.fnB();    # b 라는 변수로 fnB 메소드 실행




  // 출력 결과
A 클래스
B 클래스








3. 접근제어 지시자


    종류

        private : 인스턴스 변수와 메소드는 선언된 클래스 내부에서 접근 가능.
        protected : 상속받은 클래스에 접근을 허용.
        public : 어디서든 접근 가능한 인스턴스 변수 및 메소드. 
✱ 파이썬도 지원하지만 파이썬 private 는  변수앞 언더바( _ ) 두개, protected 는 변수앞 언더바 한개로 선언.


    C++ 접근제어 지시자 예제
      #include &lt;iostream&gt;

using namespace std;

class A {
  public:
    int r1;             //r1은 클래스 내외부 접근 가능
  protected:
    int r2;             //r2는 클래스 내부 및 상속받은 클래스에서만 접근 가능
  private:
    int r3;             //r3는 클래스 내부만 접근 가능
  public:
    void add(int a, int b){   
      r1 = a+b;             //public 으로 된 r1 변수 접근 가능
      cout &lt;&lt; r1 &lt;&lt; endl;
    }
    void sub(int a, int b){
      r2 = a-b;             //protected 로 된 r2 변수 접근 가능
      cout &lt;&lt; r2 &lt;&lt; endl;
    }
    void mul(int a, int b){
      r3 = a*b;             //private 로 된 r3 변수 접근 가능
      cout &lt;&lt; r3 &lt;&lt; endl;
    }
};

class B: public A{          //B클래스는 A클래스 상속
  pubilc:
    void div(int a, int b){
      r1 = a/b;             //public 으로 된 r1 변수 접근 가능
      count &lt;&lt; r1 &lt;&lt; endl;
    }
    void rem(int a, int b){
      r2 = a%b;            //상속 받았으므로 protected 로 된 r2 변수 접근 가능
      cout &lt;&lt; r2 &lt;&lt; endl;
    }
};

void main(){
  B *b = new B();   //b 라는 이름이 클래스 B에 대한 변수 설정

  b-&gt;add(7,4);    //add는 public 함수이므로 접근 가능
  b-&gt;sub(7,4);    //sub는 public 함수이므로 접근 가능
  b-&gt;mul(7,4);    //mul는 public 함수이므로 접근 가능
  b-&gt;div(7,4);    //div는 public 함수이므로 접근 가능
  b-&gt;rem(7,4);    //rem는 public 함수이므로 접근 가능
}



    Java 접근제어 지시자 예제
      public class A{
  public int r1;                //r1은 클래스 내외부 접근 가능
  protected int r2;             //r2는 클래스 내부 및 상속받은 클래스에서 접근 가능
  private int r3;               //r3는 클래스 내부만 접근 가능

  public void add(int a, int b){
    r1 = a+b;                   //public 인 r1 변수에 접근 가능
    System.out.println(r1);
  }
  public void sub(int a, int b){
    r2 = a-b;                   //protected 인 r2 변수에 접근 가능
    System.out.println(r2);
  }
  public void mul(int a, int b){
    r3 = a*b;                   //private 로 되어있는 r3 변수 접근 가능
    System.out.println(r3);
  }
}

public class B extends A {      // B클래스는 A 클래스 상속
  void div (int a, int b){
    r1 = a/b;                   //A클래스에 public인 r1변수 접근 가능
    System.out.println(r1);
  }
  void rem (int a, int b){      
    r2 = a%b;                   //A클래스에 protected인 r2변수 접근 가능(상속받았으니까)
    System.out.println(r2);
  }
}

public class MainTest {
  public static void main(String[] args){
    B b = new B();      //b 라는 이름의 클래스 B에 대한 변수 설정
    b.add(7,4);         //add는 public 함수이므로 접근 가능
    b.sub(7,4);         //sub는 public 함수이므로 접근 가능
    b.mul(7,4);         //mul은 public 함수이므로 접근 가능
    b.div(7,4);         //div는 public 함수이므로 접근 가능
    b.rem(7,4);         //rem은 public 함수이므로 접근 가능
  }
}




