3
28
1
3








4. 오버로딩(Overloading)


    동일 이름의 메소드를 여러개 정의할 수 있는 특성 - C++, JAVA
    오버로딩 특징

        메소드 이름이 같아야 한다.
        매개변수 개수가 달라야 한다.
        매개변수 개수가 같을 경우 데이터 타입이 달라야 한다.
        반환형은 같거나 달라도 된다.
        파이썬은 메소드 오버로딩을 지원하지 않는다.


    C++ 오버로딩(Overloading) 예제
      #include &lt;iostream&gt;

using namespace std;

class A {       // A 클래스 선언
  pubilc:
    void fund(){    // 매개변수가 없고 반환 값도 없는 func() 메소드
      count &lt;&lt; "매개변수 없음" &lt;&lt; endl;
    }
    void func(int i){ //하나의 정수형 매개변수를 갖고 반환값이 없는 func() 메소드
      count &lt;&lt; i &lt;&lt; endl;
    }
    void func(double d){  //하나의 실수형 매개변수를 갖고 반환값이 없는 func() 메소드
      count &lt;&lt; d &lt;&lt; endl;
    }
    int func(int a, int b){ //두개의 매개변수를 갖고 정수형 반환값이 있는 func() 메소드
      return a+b;
    }
};

void main(){
  A *a = new A();   //a 라는 이름이 클래스 A에 대한 변수 설정

  a-&gt;func();    //매개변수 없는 func() 메소드 호출
  a-&gt;func(7);   //하나의 정수형 매개변수를 갖는 func()메소드 호출
  a-&gt;func(10.0);  //하나의 실수형 매개변수를 갖는 func() 메소드 호출
  cout &lt;&lt; a-&gt;func(2,3) &lt;&lt; endl; //두개의 매개변수를 갖고 반환값을 갖는 func() 메소드 호출
}



    Java 오버로딩(Overloading) 예제
      public class A{     //A클래스 선언

  public void func(){      // 매개변수가 없고 반환 값도 없는 func() 메소드
    System.out.println("매개변수 없음");
  }   
  public void func(int i){  //하나의 정수형 매개변수를 갖고 반환값이 없는 func() 메소드
    System.out.println(i);
  }
  public void func(double d){  //하나의 실수형 매개변수를 갖고 반환값이 없는 func() 메소드
    System.out.println(d);
  }
  public int func(int a, int b){   //두개의 매개변수를 갖고 정수형 반환값이 있는 func() 메소드
    return a+b;
  }
}

public class MainTest {
  public static void main(String[] args){
    A a = new A();      // 클래스 A의 객체 a 생성
    a.func();           //매개변수 없는 func() 메소드 호출
    a.func(7);         //하나의 정수형 매개변수를 갖는 func()메소드 호출
    a.func(10.0);     //하나의 실수형 매개변수를 갖는 func() 메소드 호출
    System.out.println(a.func(2,3));    //두개의 매개변수를 갖고 반환값을 갖는 func() 메소드 호출
  }
}




  // 출력 결과
매개변수 없음
7
10.0
5








5. 오버라이딩(Overriding)


    오버라이딩이란 하위 클래스에서 상위클래스 메소드를 재정의 할 수 있는 특성이다.
    오버라이딩 특징

        오버라이드 하고자 하는 메소드가 상위 클래스에 존재하여야 한다.
        메소드 이름은 같아야 한다.
        메소드 매개변수 개수, 데이터 타입이 같아야 한다.
        메소드 반환형이 같아야 한다.


    C++ 오버라이딩(Overriding) 예제
      #include &lt;iostream&gt;

using namespace std;

class A {   // 부모클래스 A 선언
  public:
    virtual void info(){    //메소드 오버라이드를 위한 info 메소드 선언부 앞에 virtual 키워드를 붙임
      cout &lt;&lt; "Parent" &lt;&lt; endl; //"Parent" 글씨 출력
    }
};

class B: public A { //A클래스를 상속받은 자식클래스 B 선언
  public:
    //메소드 오버라이드를 위한 메소드 선언부앞에 virtual 붙임, 뒤에는 override 키워드 붙임.
    virtual void info() override{ 
      A::info();      //부모클래스 info 메소드 호출
      cout &lt;&lt; "Child" &lt;&lt; endl;  //"Child" 글씨 출력
    }
};

void main(){
  A *a = new B();     // 부모 클래스 변수 타입으로 선언하고 자식클래스로 생성(동적바인딩)
  a-&gt;info();    // a라는 변수로 info 메소드 호출
}


    Java 오버라이딩(Overriding) 예제
      public class A{       //부모클래스 A선언
  public void info(){       //메소드 오버라이드를 위한 info메소드 선언
    System.out.println("Parent");  //"Parent" 글자 출력
  }
}

public class B extends A{       //부모클래스 A를 상속받은 자식클래스 B 선언
  public void info(){
    super.info();               //info 메소드 선언 및 오버라이드함
    System.out.print("Child");  //"Child" 글자 출력
  }
}

public class MainTest{
  public static void main(String[] args){
    A a = new B();              // 부모클래스 변수타입으로 선언하고 자식클래스로 생성(동적바인딩)
    a.info();                 //a 라는 변수로 info 메소드 호출
  }
}




  // 출력 결과
Parent
Child










6. 인터페이스(Interface)


    자바의 다형성을 극대화 하여 개발코드 수정을 줄이고 프로그램 유지보수성을 높이기 위한 문법.
    인터페이스는 일종의 추상클래스 이다.
    오직 추상메소드와 상수만을 멤버로 가질 수 있으며, 그외 다른 어떠한 요소도 허용하지 않는다.

      인터페이스는 구현된것이 아무것도 없고 밑그림만 있는 “기본설계도”라 할 수 있다.

    C++ 인터페이스 예제
      #include &lt;iostream&gt;
#define interface struct         //구조체를 이용하여 인터페이스 정의

using namespace std;
interface A {               // 인터페이스 A 선언
  virtual void callTest()=0;  //추상메소드를 통해 callTest를 정의
};

class B: public A{    //인터페이스 A를 상속받은 클래스 B선언
  public:
    virtual void callTest(){    //callTest 메소드를 통해 "Interface Test"를 출력
      cout &lt;&lt; "Interface Test" &lt;&lt; endl;
    }
};

void main(){
  A *b = new B();   //A객체 타입의 B 객체 생성
  b-&gt;callTest();    //callTest 메소드를 호출
}


    Java 인터페이스 예제
      interface A{            // A 인터페이스 선언
  void callTest();      //callTest 메소드 선언
}

class B implements A{           //A를 구현하는 B클래스 선언
  public void callTest(){           
    System.out.println("Interface Test");       // "Interface Test" 글자 출력
  }
}

class MainTest{
  public static void main(String[] args){
    A b = new B();              //A객체 타입의 B객체 생성
    b.callTest();               //callTest 메소드 호출
  }
}




  // 출력 결과
Interface Test








7. 추상 클래스(Abstract Class)


    추상클래스란 미구현 추상 메소드를 한개 이상 가지며, 자식 클래스에서 해당 추상메소드를 반드시 구현하도록 강제하는 문법이다.
    상속받은 클래스는 추상메소드를 구현하지 않아도, import 할 때까지 에러는 발생하지 않으나 객체를 생성할 시 에러가 발생한다.
    추상 클래스의 장점

        중복코드 제거 : 상속을 통해 중복코드를 줄일 수 있음.
        그룹화 : 자식 클래스를 그룹화가 가능.
        비 실존 객체 생성 차단 : 비 실존 객체의 직접 생성을 차단하여 실수를 사전 방지.


    C++ 추상클래스 예제
      #include &lt;iostream&gt;

using namespace std;

class A {   // 추상클래스 A 선언
  public:
    virtual void callTest()=0;
};

class B: public A{    //A를 상속받은 클래스 B 선언
  public:
    virtual void callTest(){
      cout &lt;&lt; "B 클래스" &lt;&lt; endl;    // callTest() 메소드를 통해 "B 클래스" 글자 출력
    }
};

class C: public A{      //A를 상속받은 클래스 C 선언
  public:
    virtual void callTest(){
      cout &lt;&lt; "C 클래스" &lt;&lt; endl;     // callTest() 메소드를 통해 "C 클래스" 글자 출력
    }
};

void main(){
  A *b = new B();   //A 객체 변수a 에 B객체 생성
  A *c = new C();   //A 객체 변수c 에 c객체 생성
  b-&gt;callTest();    //callTest 메소드 호출
  c-&gt;callTEst();    //callTest 메소드 호출
}


    Java 추상클래스 예제
      abstract class A {              //추상클래스 A 선언
  abstract void callTest();     //추상메소드 callTest() 선언 
}

class B extends A {     //A를 상속받은 B 
  void callTest(){
    System.out.println("B 클래스");    //callTest 메소드를 통해 "B 클래스" 글자 출력
  }
}

class C extends A {     //A를 상속받은 C
  void callTest(){  
    System.out.println("C 클래스");    //callTest 메소드를 통해 "C 클래스" 글자 출력
  }
}

class MainTest{
  public static void main (String[] args){
    A b = new B();          //B객체 생성
    A c = new C();          //C객체 생성
    b.callTest();           //callTest 메소드 호출
    c.callTest();           //callTest 메소드 호출
  }
}


    파이썬 추상클래스 예제
      class A:                # 추상클래스 A 선언
  def callTest(self):   # 추상메소드 callTest() 선언
    pass                # 메소드 냉ㅇ을 채우지 않음.

class B(A):             # A를 상속받은 B
  def callTest(self):
    print('B 클래스')    #'B 클래스' 글자 출력

class C(A):             # A를 상속받은 C
  def callTest(self):   
    print('C 클래스')    # 'C 클래스' 글자 출력

b = B()             #b라는 변수명으로 B 객체 생성
c = C()             #c라는 변수명으로 C 객체 생성 
b.callTest()        #b변수로 callTest 호출
c.callTest()        #c변수로 callTest 호출





  // 출력 결과
B 클래스 
C 클래스 








8. 인터페이스와 추상 클래스의 비교

  8.1. 인터페이스와 추상 클래스 공통점

    추상클래스와 인터페이스는 선언만 있고 구현 내용이 없는 클래스이다.
    자기 자신이 new를 이용해 객체를 생성할 수 없으며, 추상클래스를 extends 받거나 interface를 implements한 자식만이 객체를 생성할 수 있다. 상속받은 자식이 구현을 반드시 하도록 해야 할 때 사용한다.
    JAVA에서는 타입이 지정되었기 때문에 선언된 타입과 자식의 타입이 같아야만 한다.




  8.2. 인터페이스와 추상클래스의 차이점

    상속을 받음에도 불구하고 클래스에선 상속(Inheritance)이라고 쓰지만, 인터페이스는 구현(Implements)이라고 쓴다.
    추상클래스를 상속받는 클래스는 반드시 추상메소드를 구현해야 한다. 필수적으로 구현해야 할 메소드가 있을때 추상 클래스를 쓰게 된다.
    인터페이스를 상속받는 클래스에서는 반드시 인터페이스에 있는 메소드를 다 구현해야 한다.














