  수학
  다이나믹 프로그래밍
  그리디 알고리즘







   예제입력 1    



18






   예제출력 1    



    4










   예제입력 2    



4






   예제출력 2    



    -1










   예제입력 3    



6






   예제출력 3    



    2










   예제입력 4    



9






   예제출력 4    



    3










   예제입력 5    



11






   예제출력 5    



    3











풀이 1

import java.util.*;

public class No2839_설탕배달 {
  public static void main(String[] args) {

    go();

  }

  public static void go(){
    Scanner sc = new Scanner(System.in);
    int kg = sc.nextInt();
    int bg = -1;         // 들고가야할 봉지 갯수
    int b1=0; int b2=0; //각 봉지 갯수
    boolean result = false;
    for(int x=(kg/5); x &gt;= 0 ; x--){
      b1 = x; b2 = 0;
      if((5*x)== kg) result = true;
      for(int y=1; y &lt;= (kg-(5*x))/3 ; y++){
        if((5*x)+(y*3) == kg) {
          result = true;
          b2 = y;
        }
        if(result) break;
      }
      if(result) break;
    }
    if(result) bg = b1+b2;
    System.out.println(bg);
  }
}










풀이 2

import java.util.*;

public class No2839_설탕배달 {
  public static void main(String[] args) {

    go2();

  }

  public static void go2(){
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int temp=n;
    int res=0;
    for(int x=n/5; x&gt;=0; x--){
      temp = n;
      res = x;
      temp = temp-(res*5);
      res+= temp/3;
      temp = temp-((temp/3)*3);
      if(temp==0) break;
    }
    System.out.println(temp!=0?-1:res);
  }

}









