package com.dev.수학;

import java.util.*;

public class No2748_피보나치수2 {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    long res = go2(n);
    System.out.println(res);
    System.out.println();

  }

  private static long go2(int n){
    long n1=0;
    long n2=1;
    long temp;
    for(int x=2; x &lt;= n; x++){
      temp = n1+n2;
      n1=n2;
      n2=temp;
    }
    return n2;
  }

}





풀이 2

package com.dev.수학;

import java.util.*;

public class No2748_피보나치수2 {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    long res = go(n);
    System.out.println(res);
    System.out.println();
  }

  public static long go(int n){
    long f = 0;
    long s = 1;
    long r = 1;
    for(int x=3; x&lt;=(n+1); x++){
      r = f+s;
      f = s;
      s = r;
    }
    return r;
  }
}








