import java.io.*;
import java.util.Scanner;

public class No2675_문자열반복 {

  public static void main(String[] args) {
    go2();
  }

  public static void go2() {
    Scanner sc = new Scanner(System.in);
    int t = sc.nextInt();
    String result = "";  //반복횟수
    int r = 0;
    String S = "";  //반복할 문자열
    for(int x=0; x&lt;t; x++){
      r = sc.nextInt();
      S = sc.next();
      for(int y=0; y&lt;S.length(); y++){
        for(int z=0; z&lt;r; z++){
          result+=S.charAt(y)+"";
        }
      }
      result+="\n";
    }
    System.out.print(result);

  }


}









