package com.dev.기타;

import java.util.Scanner;

public class No2562_최댓값 {


  public static void main(String[] args) {
    go();
  }

  public static void go(){
    Scanner sc = new Scanner(System.in);
    int max=0;
    int idx=0;
    int cur = 0;
    for(int x=0; x&lt;9; x++){
      cur = sc.nextInt();
      if(cur &gt; max) {
        max = cur;
        idx = x+1;
      }
    }
    System.out.println(max);
    System.out.println(idx);
  }
}










