import java.util.Scanner;

public class Main {

  public static void main(String[] args) {
    go();   //처음 풀었을때 방식
  }

  //첫번째 풀이 방식
  public static void go(){
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int move = 1;
    int s = 1, e=1;
    while (true){
      if(n&gt;=s &amp;&amp; n&lt;=e) break;
      s=e+1;
      e=move*6+s-1;
      move++;
    }
    System.out.println(move);
  }

}






풀이 2

import java.util.Scanner;

public class Main {

  public static void main(String[] args) {

    go2();  //두번째 풀었을때
  }

  //두번째 풀이 방식
  private static void go2(){
    Scanner sc = new Scanner(System.in);
    int n=sc.nextInt(); //도착해야 하는 번호
    int s=1;    //시작번호
    int e = 1;  //종료번호
    int g = 1;  //범위내 이동칸수
    while (!(n&gt;=s &amp;&amp; n&lt;=e)){
      s = e+1;
      e = s+(g*6)-1;
      g++;
    }
    System.out.println(g);

  }

}









