풀이 1

import java.io.*;
import java.util.*;

public class Main {
  public static void main(String[] args) {
    try{
      go();
    }catch(Exception e){ e.printStackTrace(); }

  }

  public static void go(){
    Scanner sc = new Scanner(System.in);
    String str = sc.next().toUpperCase();

    Map&lt;String, Integer&gt; m = new HashMap&lt;String, Integer&gt;();
    String i; String maxStr = ""; int max = 0; int maxCnt = 0;
    for(int x=0; x&lt;str.length(); x++){
      i = str.substring(x, x+1);
      m.put(i, m.get(i)==null?1:m.get(i)+1);
      if(max &lt; m.get(i)) max = m.get(i);
    }
    Iterator&lt;String&gt; it = m.keySet().iterator();
    it = m.keySet().iterator();
    while(it.hasNext()){
      i = it.next();
      if(m.get(i)==max) {
        maxStr = i;
        maxCnt++;
      }
    }
    if(maxCnt == 1) System.out.println(maxStr);
    else System.out.println("?");
  }

}









풀이 2

import java.io.*;
import java.util.*;

public class Main {
  public static void main(String[] args) {
    try{
      go2();
    }catch(Exception e){ e.printStackTrace(); }

  }

  public static void go2() throws IOException{

    BufferedReader br = new BufferedReader( new InputStreamReader( System.in ) );
    BufferedWriter bw = new BufferedWriter( new OutputStreamWriter( System.out ) );
    String s = br.readLine();
    s = s.toUpperCase();
    String[] sArr = s.split("");
    Arrays.sort(sArr);
    String curStr="";
    String maxStr="";
    int curStrCnt=0;
    int maxCnt = 0;
    List&lt;Integer&gt; list = new ArrayList&lt;Integer&gt;();
    for (int i = 0; i &lt; sArr.length; i++) {
      if(!curStr.equals(sArr[i])){
        if(i!=0)list.add(curStrCnt);
        if(curStrCnt &gt;= maxCnt ) {
          maxCnt = curStrCnt;
          maxStr = curStr;
        }
        curStr = sArr[i];
        curStrCnt = 1;
      }else curStrCnt++;
    }
    if(curStrCnt &gt;= maxCnt )  {
      maxStr = curStr;
      maxCnt = curStrCnt;
    }
    list.add(curStrCnt);
    int maxStrCnt = 0;
    for (int size : list) {
      if(size == maxCnt) maxStrCnt++;
    }
    if(maxStrCnt==1) bw.write(maxStr+"");
    else bw.write("?");


    bw.flush();
    bw.close();
    br.close();
  }

}








